// UpdateUpdatedAt sets the "updated_at" field to the value that was provided on create.
func (u *AuthLockoutUpsertBulk) UpdateUpdatedAt() *AuthLockoutUpsertBulk {
	return u.Update(func(s *AuthLockoutUpsert) {
		s.UpdateUpdatedAt()
	})
}

// Exec executes the query.
func (u *AuthLockoutUpsertBulk) Exec(ctx context.Context) error {
	if u.create.err != nil {
		return u.create.err
	}
	for i, b := range u.create.builders {
		if len(b.conflict) != 0 {
			return fmt.Errorf("ent: OnConflict was set for builder %d. Set it on the AuthLockoutCreateBulk instead", i)
		}
	}
	if len(u.create.conflict) == 0 {
		return errors.New("ent: missing options for AuthLockoutCreateBulk.OnConflict")
	}
	return u.create.Exec(ctx)
}

// ExecX is like Exec, but panics if an error occurs.
func (u *AuthLockoutUpsertBulk) ExecX(ctx context.Context) {
	if err := u.create.Exec(ctx); err != nil {
		panic(err)
	}
}
